+use crate::api::client::ApiClient;
+use crate::constants;
+use crate::models::{ResultWithDefaultError, TimeEntry};
+use crate::utilities;
+use std::collections::HashMap;
+
+const BILLING_UNIT_SECONDS: i64 = 15 * 60;
+
+pub struct BillCommand;
+
+impl BillCommand {
+    pub async fn execute(
+        api_client: impl ApiClient,
+        since: Option<String>,
+        until: Option<String>,
+    ) -> ResultWithDefaultError<()> {
+        let (since, until) = if since.is_some() || until.is_some() {
+            utilities::normalize_time_entry_list_filters(since, until)?
+        } else {
+            (None, None)
+        };
+        let entries = api_client.get_time_entries_filtered(since, until).await?;
+        let totals = aggregate_billable_entries(&entries);
+
+        if totals.is_empty() {
+            println!("(no data)");
+            return Ok(());
+        }
+
+        let total: i64 = totals.iter().map(|(_, seconds)| seconds).sum();
+        for (project, seconds) in totals {
+            println!("{seconds}s  {project}");
+        }
+        println!("{total}s  Total");
+        Ok(())
+    }
+}
+
+/// Aggregate stopped billable entries, rounding each entry up independently.
+pub fn aggregate_billable_entries(entries: &[TimeEntry]) -> Vec<(String, i64)> {
+    let mut totals = HashMap::<String, i64>::new();
+
+    for entry in entries {
+        if !entry.billable || entry.stop.is_none() || entry.is_running() || entry.duration <= 0 {
+            continue;
+        }
+
+        let rounded = ((entry.duration + BILLING_UNIT_SECONDS - 1) / BILLING_UNIT_SECONDS)
+            * BILLING_UNIT_SECONDS;
+        let project = entry
+            .project
+            .as_ref()
+            .map(|project| project.name.clone())
+            .unwrap_or_else(|| constants::NO_PROJECT.to_string());
+        *totals.entry(project).or_default() += rounded;
+    }
+
+    let mut totals: Vec<_> = totals.into_iter().collect();
+    totals.sort_by(|(left_name, left_seconds), (right_name, right_seconds)| {
+        right_seconds
+            .cmp(left_seconds)
+            .then_with(|| left_name.cmp(right_name))
+    });
+    totals
+}
+
+#[cfg(test)]
+mod tests {
+    use super::*;
+    use crate::api::client::MockApiClient;
+    use crate::models::{Project, TimeEntry};
+    use chrono::{TimeZone, Utc};
+
+    fn entry(
+        duration: i64,
+        billable: bool,
+        stop: Option<i64>,
+        project: Option<&str>,
+    ) -> TimeEntry {
+        TimeEntry {
+            id: duration,
+            description: String::new(),
+            start: Utc.timestamp_opt(1_700_000_000, 0).single().unwrap(),
+            stop: stop.map(|seconds| Utc.timestamp_opt(seconds, 0).single().unwrap()),
+            duration,
+            billable,
+            workspace_id: 1,
+            tags: Vec::new(),
+            project: project.map(|name| Project {
+                id: 1,
+                name: name.to_string(),
+                workspace_id: 1,
+                client: None,
+                is_private: false,
+                active: true,
+                at: Utc.timestamp_opt(1_700_000_000, 0).single().unwrap(),
+                created_at: Utc.timestamp_opt(1_700_000_000, 0).single().unwrap(),
+                color: String::new(),
+                billable: None,
+            }),
+            task: None,
+            created_with: None,
+        }
+    }
+
+    #[test]
+    fn rounds_each_billable_entry_before_summing_and_sorts_results() {
+        let entries = vec![
+            entry(22 * 60, true, Some(1_700_000_100), Some("Beta")),
+            entry(7 * 60, true, Some(1_700_000_100), Some("Alpha")),
+            entry(15 * 60, true, Some(1_700_000_100), Some("Beta")),
+            entry(60 * 60, true, Some(1_700_000_100), None),
+        ];
+
+        assert_eq!(
+            aggregate_billable_entries(&entries),
+            vec![
+                (constants::NO_PROJECT.to_string(), 3600),
+                ("Beta".to_string(), 2700),
+                ("Alpha".to_string(), 900),
+            ]
+        );
+    }
+
+    #[test]
+    fn ignores_non_billable_running_and_non_positive_entries() {
+        let entries = vec![
+            entry(60, false, Some(1_700_000_100), Some("Ignored")),
+            entry(-60, true, None, Some("Ignored")),
+            entry(0, true, Some(1_700_000_100), Some("Ignored")),
+        ];
+
+        assert!(aggregate_billable_entries(&entries).is_empty());
+    }
+
+    #[tokio::test]
+    async fn uses_normalized_date_filters() {
+        let mut api_client = MockApiClient::new();
+        let (expected_since, expected_until) =
+            utilities::normalize_time_entry_list_filters(
+                Some("2026-01-01".to_string()),
+                Some("2026-01-31".to_string()),
+            )
+            .unwrap();
+        api_client
+            .expect_get_time_entries_filtered()
+            .withf(move |since, until| *since == expected_since && *until == expected_until)
+            .returning(|_, _| Ok(Vec::new()));
+
+        BillCommand::execute(
+            api_client,
+            Some("2026-01-01".to_string()),
+            Some("2026-01-31".to_string()),
+        )
+        .await
+        .unwrap();
+    }
+}
